typedef void (*naupd_t)(void*, double*, double*, int, int*, double*, double*);
static void matvec(int n, const int* restrict ip, const int* restrict ix, const double* restrict d,
                   const double* restrict x, double* restrict y) {
    int i = 0;
    for (; i + 4 <= n; i += 4) {
        int a0 = ip[i], e0 = ip[i+1], a1 = e0, e1 = ip[i+2], a2 = e1, e2 = ip[i+3], a3 = e2, e3 = ip[i+4];
        double s0 = 0.0, s1 = 0.0, s2 = 0.0, s3 = 0.0;
        int l0 = e0 - a0, l1 = e1 - a1, l2 = e2 - a2, l3 = e3 - a3;
        int m = l0; if (l1 < m) m = l1; if (l2 < m) m = l2; if (l3 < m) m = l3;
        for (int t = 0; t < m; t++) {
            s0 += d[a0+t] * x[ix[a0+t]];
            s1 += d[a1+t] * x[ix[a1+t]];
            s2 += d[a2+t] * x[ix[a2+t]];
            s3 += d[a3+t] * x[ix[a3+t]];
        }
        for (int j = a0 + m; j < e0; j++) s0 += d[j] * x[ix[j]];
        for (int j = a1 + m; j < e1; j++) s1 += d[j] * x[ix[j]];
        for (int j = a2 + m; j < e2; j++) s2 += d[j] * x[ix[j]];
        for (int j = a3 + m; j < e3; j++) s3 += d[j] * x[ix[j]];
        y[i] = s0; y[i+1] = s1; y[i+2] = s2; y[i+3] = s3;
    }
    for (; i < n; i++) {
        double s = 0.0;
        for (int j = ip[i]; j < ip[i+1]; j++) s += d[j] * x[ix[j]];
        y[i] = s;
    }
}
