#include <stdlib.h>
#include <string.h>
/* group rows with identical length into blocks of G; same per-row summation order -> bit-identical */
#define G 4
typedef struct { int nb; int* blen; int* bstart; int* rows; double* d; int* ix;
                 int nrest; int* rrows; } grp_t;
static const int* g_ip;
static int g_cmp(const void* a, const void* b) {
    int ra = *(const int*)a, rb = *(const int*)b;
    int la = g_ip[ra+1]-g_ip[ra], lb = g_ip[rb+1]-g_ip[rb];
    return la != lb ? la - lb : ra - rb;
}
static int grp_build(grp_t* g, int n, const int* ip, const int* ix, const double* d) {
    int* ord = malloc(sizeof(int) * (n > 0 ? n : 1));
    for (int i = 0; i < n; i++) ord[i] = i;
    g_ip = ip; qsort(ord, n, sizeof(int), g_cmp);
    g->blen = malloc(sizeof(int) * (n / G + 1)); g->bstart = malloc(sizeof(int) * (n / G + 1));
    g->rows = malloc(sizeof(int) * (n + 1)); g->rrows = malloc(sizeof(int) * (n + 1));
    long nnz = ip[n];
    g->d = malloc(sizeof(double) * (nnz + 1)); g->ix = malloc(sizeof(int) * (nnz + 1));
    g->nb = 0; g->nrest = 0;
    long pos = 0;
    int i = 0;
    while (i < n) {
        int L = ip[ord[i]+1]-ip[ord[i]]; int j = i;
        while (j < n && ip[ord[j]+1]-ip[ord[j]] == L) j++;
        int k = i;
        for (; k + G <= j; k += G) {
            int b = g->nb++;
            g->blen[b] = L; g->bstart[b] = (int)pos;
            for (int r = 0; r < G; r++) {
                int row = ord[k+r]; g->rows[b*G + r] = row;
                for (int t = 0; t < L; t++) {
                    g->d[pos + (long)t*G + r] = d[ip[row]+t];
                    g->ix[pos + (long)t*G + r] = ix[ip[row]+t];
                }
            }
            pos += (long)L * G;
        }
        for (; k < j; k++) g->rrows[g->nrest++] = ord[k];
        i = j;
    }
    free(ord);
    return 0;
}
static void grp_free(grp_t* g) { free(g->blen); free(g->bstart); free(g->rows); free(g->rrows); free(g->d); free(g->ix); }
static void grp_mv(const grp_t* g, const int* restrict ip, const int* restrict ix, const double* restrict d,
                   const double* restrict x, double* restrict y) {
    for (int b = 0; b < g->nb; b++) {
        int L = g->blen[b];
        const double* restrict dp = g->d + g->bstart[b];
        const int* restrict xp = g->ix + g->bstart[b];
        double s0 = 0.0, s1 = 0.0, s2 = 0.0, s3 = 0.0;
        for (int t = 0; t < L; t++) {
            s0 += dp[4*t+0] * x[xp[4*t+0]];
            s1 += dp[4*t+1] * x[xp[4*t+1]];
            s2 += dp[4*t+2] * x[xp[4*t+2]];
            s3 += dp[4*t+3] * x[xp[4*t+3]];
        }
        const int* rr = g->rows + 4*b;
        y[rr[0]] = s0; y[rr[1]] = s1; y[rr[2]] = s2; y[rr[3]] = s3;
    }
    for (int q = 0; q < g->nrest; q++) {
        int i = g->rrows[q]; double s = 0.0;
        for (int j = ip[i]; j < ip[i+1]; j++) s += d[j] * x[ix[j]];
        y[i] = s;
    }
}
