#include <pthread.h>
#include <stdatomic.h>
#include <stdint.h>
#include "grp.h"
typedef void (*naupd_t)(void*, double*, double*, int, int*, double*, double*);
#define MAXT 16

/* sub-CSR for a row range, built by the owning thread */
typedef struct { int r0, r1; int* ip; int* ix; double* d; grp_t g; } part_t;

static void part_build(part_t* p, int r0, int r1, const int* ip, const int* ix, const double* d) {
    int m = r1 - r0; p->r0 = r0; p->r1 = r1;
    int base = ip[r0], nnz = ip[r1] - base;
    p->ip = malloc(sizeof(int) * (m + 1)); p->ix = malloc(sizeof(int) * (nnz + 1)); p->d = malloc(sizeof(double) * (nnz + 1));
    for (int i = 0; i <= m; i++) p->ip[i] = ip[r0 + i] - base;
    memcpy(p->ix, ix + base, sizeof(int) * nnz); memcpy(p->d, d + base, sizeof(double) * nnz);
    grp_build(&p->g, m, p->ip, p->ix, p->d);
}
static void part_free(part_t* p) { grp_free(&p->g); free(p->ip); free(p->ix); free(p->d); }
static inline void part_mv(const part_t* p, const double* x, double* y) { grp_mv(&p->g, p->ip, p->ix, p->d, x, y + p->r0); }

typedef struct {
    const int* ip; const int* ix; const double* d;
    const double* volatile x; double* volatile y;
    int bounds[MAXT + 1];
    part_t parts[MAXT];
    _Atomic int gen; _Atomic int done; _Atomic int quit; _Atomic int ready;
} shared_t;
typedef struct { shared_t* s; int id; } targ_t;

static void* worker(void* arg) {
    targ_t* a = (targ_t*)arg; shared_t* s = a->s; int id = a->id;
    part_t* p = &s->parts[id];
    part_build(p, s->bounds[id], s->bounds[id+1], s->ip, s->ix, s->d);
    atomic_fetch_add(&s->ready, 1);
    int seen = 0;
    for (;;) {
        int g;
        while ((g = atomic_load_explicit(&s->gen, memory_order_acquire)) == seen) {
            if (atomic_load_explicit(&s->quit, memory_order_relaxed)) { part_free(p); return 0; }
            __builtin_ia32_pause();
        }
        seen = g;
        part_mv(p, s->x, s->y);
        atomic_fetch_add_explicit(&s->done, 1, memory_order_release);
    }
}

int run_loop(void* fn, void* state, double* resid, double* v, int ldv, int* ipntr,
             double* workd, double* workl, int n, const int* indptr, const int* indices,
             const double* data, int nthreads, int mainshare) {
    naupd_t f = (naupd_t)fn;
    int* ido = (int*)((char*)state + 0x34);
    if (nthreads < 1) nthreads = 1;
    if (nthreads > MAXT) nthreads = MAXT;
    static shared_t s; pthread_t th[MAXT]; targ_t ta[MAXT];
    s.ip = indptr; s.ix = indices; s.d = data;
    atomic_store(&s.gen, 0); atomic_store(&s.done, 0); atomic_store(&s.quit, 0); atomic_store(&s.ready, 0);
    long nnz = indptr[n];
    /* part 0 = main thread share (mainshare %), rest split evenly */
    s.bounds[0] = 0; int r = 0;
    for (int t = 1; t < nthreads; t++) {
        double frac = mainshare / 100.0 + (1.0 - mainshare / 100.0) * (t - 1) / (double)(nthreads - 1);
        long target = (long)(nnz * frac);
        while (r < n && indptr[r] < target) r++;
        s.bounds[t] = r;
    }
    s.bounds[nthreads] = n;
    int nw = 0;
    for (int t = 1; t < nthreads; t++) {
        ta[t].s = &s; ta[t].id = t;
        if (pthread_create(&th[t], 0, worker, &ta[t]) != 0) break;
        nw++;
    }
    if (nw != nthreads - 1) s.bounds[nw + 1] = n;   /* main covers leftover via its part bounds */
    int mend = (nw == 0) ? n : s.bounds[1];
    part_t* p0 = &s.parts[0];
    part_build(p0, 0, mend, indptr, indices, data);
    /* if thread creation failed partially, main also handles [bounds[nw+1], n) -- covered above by setting bounds */
    part_t extra; int has_extra = 0;
    if (nw != nthreads - 1 && nw > 0 && s.bounds[nw+1] < n) { part_build(&extra, s.bounds[nw+1], n, indptr, indices, data); has_extra = 1; }
    while (atomic_load(&s.ready) != nw) __builtin_ia32_pause();
    int gen = 0, ret;
    for (;;) {
        f(state, resid, v, ldv, ipntr, workd, workl);
        if (*ido == 1 || *ido == 5) {
            const double* x = workd + ipntr[0]; double* y = workd + ipntr[1];
            if (nw == 0) { part_mv(p0, x, y); continue; }
            s.x = x; s.y = y;
            atomic_store_explicit(&s.done, 0, memory_order_relaxed);
            atomic_store_explicit(&s.gen, ++gen, memory_order_release);
            part_mv(p0, x, y);
            if (has_extra) part_mv(&extra, x, y);
            while (atomic_load_explicit(&s.done, memory_order_acquire) != nw) __builtin_ia32_pause();
        } else { ret = *ido; break; }
    }
    atomic_store(&s.quit, 1);
    for (int t = 1; t <= nw; t++) pthread_join(th[t], 0);
    part_free(p0); if (has_extra) part_free(&extra);
    return ret;
}
