/* rows sorted by length; blocks of 8 consecutive rows; interleave common prefix of length m=min len;
   then tails per row. Each row's summation order identical to plain CSR loop. */
typedef struct { int nb; int* bm; int* bstart; int* rows; int* tl; double* d; uint16_t* ix; int n; } g8_t;
static const int* g8_ip;
static int g8_cmp(const void* a, const void* b) {
    int ra = *(const int*)a, rb = *(const int*)b;
    int la = g8_ip[ra+1]-g8_ip[ra], lb = g8_ip[rb+1]-g8_ip[rb];
    return la != lb ? la - lb : ra - rb;
}
static int g8_build(g8_t* g, int n, const int* ip, const int* ix, const double* d) {
    int nb = (n + 7) / 8; g->nb = nb; g->n = n;
    int* ord = malloc(sizeof(int) * (nb * 8));
    for (int i = 0; i < n; i++) ord[i] = i;
    g8_ip = ip; qsort(ord, n, sizeof(int), g8_cmp);
    for (int i = n; i < nb * 8; i++) ord[i] = -1;
    g->rows = ord; g->bm = malloc(sizeof(int) * nb); g->bstart = malloc(sizeof(int) * (nb + 1));
    g->tl = malloc(sizeof(int) * nb * 8);
    long nnz = ip[n];
    g->d = malloc(sizeof(double) * (nnz + 8)); g->ix = malloc(sizeof(uint16_t) * (nnz + 8));
    long pos = 0;
    for (int b = 0; b < nb; b++) {
        int m = 1 << 30;
        for (int r = 0; r < 8; r++) { int row = ord[b*8+r]; int l = row >= 0 ? ip[row+1]-ip[row] : 0; if (l < m) m = l; }
        g->bm[b] = m; g->bstart[b] = (int)pos;
        for (int t = 0; t < m; t++) for (int r = 0; r < 8; r++) { int row = ord[b*8+r]; g->d[pos] = d[ip[row]+t]; g->ix[pos] = (uint16_t)ix[ip[row]+t]; pos++; }
        for (int r = 0; r < 8; r++) {
            int row = ord[b*8+r]; int l = row >= 0 ? ip[row+1]-ip[row] : 0;
            g->tl[b*8+r] = l - m;
            for (int t = m; t < l; t++) { g->d[pos] = d[ip[row]+t]; g->ix[pos] = (uint16_t)ix[ip[row]+t]; pos++; }
        }
    }
    g->bstart[nb] = (int)pos;
    return 0;
}
static void g8_free(g8_t* g) { free(g->rows); free(g->bm); free(g->bstart); free(g->tl); free(g->d); free(g->ix); }
static void g8_mv(const g8_t* g, const double* restrict x, double* restrict y) {
    const double* restrict dp = g->d; const uint16_t* restrict xp = g->ix;
    for (int b = 0; b < g->nb; b++) {
        int m = g->bm[b];
        double s0=0,s1=0,s2=0,s3=0,s4=0,s5=0,s6=0,s7=0;
        for (int t = 0; t < m; t++) {
            s0 += dp[0]*x[xp[0]]; s1 += dp[1]*x[xp[1]]; s2 += dp[2]*x[xp[2]]; s3 += dp[3]*x[xp[3]];
            s4 += dp[4]*x[xp[4]]; s5 += dp[5]*x[xp[5]]; s6 += dp[6]*x[xp[6]]; s7 += dp[7]*x[xp[7]];
            dp += 8; xp += 8;
        }
        double s[8] = {s0,s1,s2,s3,s4,s5,s6,s7};
        const int* tl = g->tl + 8*b; const int* rr = g->rows + 8*b;
        for (int r = 0; r < 8; r++) {
            double a = s[r]; int L = tl[r];
            for (int t = 0; t < L; t++) a += dp[t]*x[xp[t]];
            dp += L; xp += L;
            if (rr[r] >= 0) y[rr[r]] = a;
        }
    }
}
