            else { lastc = 0; for (int j = n; j >= 1; j--) { int nz = 0; for (int r = 1; r <= lastv; r++) if (c[r-1+(j-1)*ldC] != 0.0) { nz = 1; break; } if (nz) { lastc = j; break; } } }
        } else { /* iladlr(m, lastv, c) */
            if (m == 0) lastc = 0;
            else if (c[m-1] != 0.0 || c[m-1 + (lastv-1)*ldC] != 0.0) lastc = m;
            else { lastc = 0; for (int j = 1; j <= lastv; j++) { int r = m; while (r >= 1 && c[(r>1?r:1)-1 + (j-1)*ldC] == 0.0 && r >= 1) r--; if (r > lastc) lastc = r; } }
        }
    }
    if (lastv == 0 || lastc == 0) return;
    if (inc != 1) return; /* not used by ARPACK path */
    if (left) {
        for (int j = 0; j < lastc; j++) { double s = 0.0; const double* cj = c + j*ldC; for (int i = 0; i < lastv; i++) s = MADD(cj[i], v[i], s); work[j] = s; }
        for (int j = 0; j < lastc; j++) { if (work[j] != 0.0) { double tmp = -t * work[j]; double* cj = c + j*ldC; for (int i = 0; i < lastv; i++) cj[i] = MADD(v[i], tmp, cj[i]); } }
    } else {
        for (int i = 0; i < lastc; i++) work[i] = 0.0;
        for (int j = 0; j < lastv; j++) { double tmp = v[j]; if (tmp != 0.0) { const double* cj = c + j*ldC; for (int i = 0; i < lastc; i++) work[i] = MADD(tmp, cj[i], work[i]); } }
        for (int j = 0; j < lastv; j++) { if (v[j] != 0.0) { double tmp = -t * v[j]; double* cj = c + j*ldC; for (int i = 0; i < lastc; i++) cj[i] = MADD(work[i], tmp, cj[i]); } }
    }
}
