double rnd(){ return (rand()/(double)RAND_MAX-0.5)*4; }
/* k = reflector length (2 or 3), v[0]=1 */
static double dot(int k,const double*c,int stride,const double*v,int var){
  switch(var){
   case 0:{double s=0;for(int i=0;i<k;i++)s+=c[i*stride]*v[i];return s;}
   case 1:{double s=0;for(int i=0;i<k;i++)s=fma(c[i*stride],v[i],s);return s;}
   case 2:{double s=c[0]*v[0]; for(int i=1;i<k;i++) s=fma(c[i*stride],v[i],s); return s;}
   case 3:{ if(k==3) return c[0]*v[0]+(c[stride]*v[1]+c[2*stride]*v[2]); return c[0]*v[0]+c[stride]*v[1];}
   case 4:{ if(k==3) return fma(c[0],v[0],fma(c[stride],v[1],c[2*stride]*v[2])); return fma(c[0],v[0],c[stride]*v[1]);}
   case 5:{ double s=0; for(int i=k-1;i>=0;i--) s=fma(c[i*stride],v[i],s); return s;}
  }
  return 0;
}
static double upd(double c,double tau,double vi,double wj,int var){
  switch(var){
   case 0: return c + vi*(-tau*wj);
   case 1: return fma(vi,-tau*wj,c);
   case 2: return c + wj*(-tau*vi);
   case 3: return fma(wj,-tau*vi,c);
   case 4: return c - tau*(vi*wj);
   case 5: return fma(-tau, vi*wj, c);
   case 6: return c - (tau*vi)*wj;
   case 7: return fma(-(tau*vi),wj,c);
  }
  return 0;
}
int main(){
