      memcpy(C2,C0,sizeof(double)*ld*n);
      if(left){ for(int j=0;j<n;j++){ double w=dot(k,C0+j*ld,1,v,dv); for(int i=0;i<k;i++) C2[i+j*ld]=upd(C0[i+j*ld],tau,v[i],w,uv);} }
      else { for(int i=0;i<m;i++){ double w=dot(k,C0+i,ld,v,dv); for(int j=0;j<k;j++) C2[i+j*ld]=upd(C0[i+j*ld],tau,v[j],w,uv);} }
      if(!memcmp(C1,C2,sizeof(double)*ld*n)) match[dv][uv]++;
    }
   }
   printf("left=%d\n",left); for(int dv=0;dv<6;dv++){for(int uv=0;uv<8;uv++)printf("%6d",match[dv][uv]);printf("\n");}
  }
