#include <math.h>
/* Small-reflector dlarf replicating Accelerate's arithmetic for k=2,3, incv=1, v[0]=1 assumed by caller check. */
static int my_dlarf_small(const char* side, int m, int n, const double* v, double tau, double* c, int ld, int var2) {
    int left = (*side == 'L' || *side == 'l');
    int k = left ? m : n;
    if (k < 2 || k > 3) return 0;
    if (tau == 0.0) return 1;
    if (left) {
        for (int j = 0; j < n; j++) {
            double* cj = c + (long)j * ld;
            double w;
            if (k == 3) w = (cj[0] * v[0] + cj[1] * v[1]) + cj[2] * v[2];
            else        w = cj[0] * v[0] + cj[1] * v[1];
            for (int i = 0; i < k; i++) cj[i] = fma(w, -tau * v[i], cj[i]);
        }
    } else {
        double* c0 = c; double* c1 = c + ld; double* c2 = c + 2L * ld;
        for (int i = 0; i < m; i++) {
            double w;
            if (k == 3) w = fma(c2[i], v[2], c0[i]) + c1[i] * v[1];
            else {
                switch (var2) {
                case 0: w = fma(c1[i], v[1], c0[i]); break;
                case 1: w = c0[i] + c1[i] * v[1]; break;
                default: w = fma(c0[i], v[0], c1[i] * v[1]); break;
                }
            }
            for (int j = 0; j < k; j++) c[i + (long)j * ld] = fma(w, -tau * v[j], c[i + (long)j * ld]);
        }
    }
    return 1;
}
